   private String describeTrap(String name, PrintCore.m trap) {
      return trap == null
         ? " " + name + "=none"
         : " "
            + name
            + "="
            + trap.init_Z
            + "/"
            + trap.read
            + " trapped="
            + trap.intermediateTraps
            + " before="
            + (
               trap.init_UiHelper_h == null
                  ? "none"
                  : trap.init_UiHelper_h.done
                     + "/"
                     + (trap.init_UiHelper_h.search == null ? 0 : trap.init_UiHelper_h.search.expandedNodes)
            )
            + " after="
            + (
               trap.load_UiHelper_h == null
                  ? "none"
                  : trap.load_UiHelper_h.done
                     + "/"
                     + (trap.load_UiHelper_h.search == null ? 0 : trap.load_UiHelper_h.search.expandedNodes)
            );
   }

   String describeTrap(PrintCore.aI trap) {
      String detail = "trapStage=" + trap.init_I + " workstation=" + trap.workstation + " target=" + trap.load_BlockPos.toShortString();
      if (trap.init_UiHelper_e != null) {
         detail = detail
            + " escape="
            + trap.init_UiHelper_e.init_StreamUtil_TaskQue
            + " ground="
            + trap.init_UiHelper_e.groundOnly
            + " expanded="
            + (trap.init_UiHelper_e.init_StreamUtil_ConfigS == null ? 0L : trap.init_UiHelper_e.init_StreamUtil_ConfigS.expandedNodes);
      }

      if (trap.init_TokenStore_NetHelp != null) {
         detail = detail + " walkingBefore=" + trap.init_TokenStore_NetHelp.result.reachableCount() + "/" + trap.init_TokenStore_NetHelp.finished;
      }

      if (trap.load_TokenStore_NetHelp != null) {
         detail = detail + " walkingAfter=" + trap.load_TokenStore_NetHelp.result.reachableCount() + "/" + trap.load_TokenStore_NetHelp.finished;
      }

      return detail;
   }

