   public void attachItemFrames(List<autismclient.ai.print.PrintItemFrame.Inner_StreamUtil> frames) {
      for (autismclient.ai.print.PrintItemFrame.Inner_StreamUtil spec : frames) {
         long key = spec.support().asLong();
         if (!this.init_Long2ObjectLinkedO.containsKey(key) && !this.update_Long2ObjectOpenHas.containsKey(key)) {
            PrintItemFrame job = new PrintItemFrame(this.env, spec);
            this.attachMachineJob(job);
            this.view.requiredInteractFaces.put(key, spec.facing());

            for (String reason : job.skippedReasons()) {
               if (this.read_ArrayList.size() < 16) {
                  this.read_ArrayList.add(reason);
               }
            }
         } else if (this.read_ArrayList.size() < 16) {
            this.read_ArrayList.add(spec.cell().toShortString() + ": a second saved action on the block the frame hangs on");
         }
      }
   }

   public void attachMachineJob(PrintMachineJob job) {
      if (this.clear_J >= 0L) {
         throw new IllegalStateException("Attach machine actions before construction starts");
      }

      if (job.item() == Items.AIR) {
         job.init(
            () -> {
               BlockPos missingHead = this.load_BlockPos_BlockPos(job.position());
               return missingHead == null
                  ? null
                  : "Filling the container at "
                     + job.position().toShortString()
                     + " would activate an assembly before its opposing piston head stands at "
                     + missingHead.toShortString();
            }
         );
      }

      if (!(job instanceof PrintClockSequence clock)) {
         if (this.update_Long2ObjectOpenHas.containsKey(job.position().asLong())) {
            throw new IllegalArgumentException("Multiple saved actions at " + job.position().toShortString());
         }
      } else {
         for (BlockPos at : clock.accessCells()) {
            if (this.init_Long2ObjectLinkedO.containsKey(at.asLong()) || this.update_Long2ObjectOpenHas.containsKey(at.asLong())) {
               throw new IllegalArgumentException("Multiple saved actions at " + at.toShortString());
            }
         }

         for (BlockPos at : clock.dynamicCells()) {
            if (this.sync_Long2ObjectOpenHas.containsKey(at.asLong())) {
               throw new IllegalArgumentException("Overlapping clocks at " + at.toShortString());
            }
         }

         for (BlockPos at : clock.accessCells()) {
            this.update_Long2ObjectOpenHas.put(at.asLong(), clock);
         }

         for (BlockPos at : clock.dynamicCells()) {
            this.sync_Long2ObjectOpenHas.put(at.asLong(), clock);
         }
      }

      if (this.init_Long2ObjectLinkedO.putIfAbsent(job.position().asLong(), job) != null) {
         throw new IllegalArgumentException("Multiple saved actions at " + job.position().toShortString());
      }

      if (job.b_() && job.needsAccess()) {
         this.init_StateCache.init(job);
      }
   }

   public void attachMachineOutcomes(Map<BlockPos, BlockState> expected) {
      if (this.clear_J >= 0L) {
         throw new IllegalStateException("Attach machine outcomes before construction starts");
      }

      expected.forEach(
         (position, state) -> {
            long key = position.asLong();
            if (this.close_Long2ObjectOpenHas.put(key, state) == null) {
               this.open_Long2ObjectOpenHas.computeIfAbsent(PrintChunkWork.chunkKey(position), ignored -> new LongArrayList()).add(key);
            }

            this.init_LongLinkedOpenHash.add(key);
            int cell = this.cellIndexByPos.get(key);
            if (this.init_UiHelper_aE == null
               && cell >= 0
               && this.cellStates[cell] == 2
               && this.rules.acceptsUnpoweredOutput(this.targets[cell], this.view.getBlockState(position))) {
               this.init_V_I(cell);
            }
         }
      );
   }

   BlockState init_BlockState_BlockPos(BlockPos position) {
      return this.close_Long2ObjectOpenHas.get(position.asLong());
   }

