   private long init_J_TokenStore_TaskQue(PrintNav.Inner_TaskQueue reach, BlockPos c, long seed, boolean dry) {
      long h = seed;
      int tried = 0;

      for (int d = 0; d <= 4 && tried < 24; d++) {
         for (int dx = -d; dx <= d && tried < 24; dx++) {
            for (int dz = -d; dz <= d && tried < 24; dz++) {
               if (Math.max(Math.abs(dx), Math.abs(dz)) == d) {
                  for (int dy = 3; dy >= -5 && tried < 24; dy--) {
                     long key = BlockPos.asLong(c.getX() + dx, c.getY() + dy, c.getZ() + dz);
                     if (reach.isReachable(key) && (!dry || !this.push_Z_BlockPos(BlockPos.of(key)))) {
                        tried++;
                        h = h * 1000003L + key;
                        h = h * 31L + Double.doubleToLongBits(reach.feetYOf(key));
                     }
                  }
               }
            }
         }
      }

      return h * 31L + tried;
   }

