   private LongArrayList init_LongArrayList_BlockPos_J(BlockPos c, long revision) {
      if (init_J_Long2LongOpenHashM(this.view.bucketRemovalRevision, c, -8, 8, -8, 8) > revision) {
         return null;
      }

      LongArrayList out = new LongArrayList();
      int x0 = c.getX() - 5 >> 2;
      int x1 = c.getX() + 5 >> 2;
      int y0 = c.getY() - 6 >> 2;
      int y1 = c.getY() + 2 >> 2;
      int z0 = c.getZ() - 5 >> 2;
      int z1 = c.getZ() + 5 >> 2;

      for (int x = x0; x <= x1; x++) {
         for (int y = y0; y <= y1; y++) {
            for (int z = z0; z <= z1; z++) {
               long bucket = BlockPos.asLong(x, y, z);
               if (this.view.bucketAdditionRevision.get(bucket) > revision) {
                  if (this.view.bucketOverflowRevision.get(bucket) > revision) {
                     return null;
                  }

                  LongArrayList log = this.view.bucketAdditionLogs.get(bucket);
                  if (log == null) {
                     return null;
                  }

                  for (int k = 0; k < log.size(); k += 2) {
                     if (log.getLong(k) > revision) {
                        long key = log.getLong(k + 1);
                        int dx = BlockPos.getX(key) - c.getX();
                        int dy = BlockPos.getY(key) - c.getY();
                        int dz = BlockPos.getZ(key) - c.getZ();
                        if (Math.abs(dx) <= 5 && Math.abs(dz) <= 5 && dy >= -6 && dy <= 2) {
                           out.add(key);
                        }
                     }
                  }
               }
            }
         }
      }

      return out;
   }

