   private boolean init_Z_BlockPos_2(BlockPos cell, BlockPos support, long stance, double feetY) {
      VoxelShape shape = this.view.getBlockState(support).getShape(this.view, support);
      if (shape.isEmpty()) {
         return false;
      } else {
         double margin = 0.85;
         if (support.getX() != cell.getX()) {
            boolean east = support.getX() > cell.getX();
            double plane = support.getX() + (east ? shape.min(Axis.X) : shape.max(Axis.X));
            double x = BlockPos.getX(stance) + 0.5;
            return east ? x - margin < plane - 0.001 : x + margin > plane + 0.001;
         } else if (support.getZ() != cell.getZ()) {
            boolean south = support.getZ() > cell.getZ();
            double plane = support.getZ() + (south ? shape.min(Axis.Z) : shape.max(Axis.Z));
            double z = BlockPos.getZ(stance) + 0.5;
            return south ? z - margin < plane - 0.001 : z + margin > plane + 0.001;
         } else {
            boolean up = support.getY() > cell.getY();
            double plane = support.getY() + (up ? shape.min(Axis.Y) : shape.max(Axis.Y));
            return up ? feetY + 1.27 < plane - 0.001 : feetY + 1.62 > plane + 0.001;
         }
      }
   }

