   private boolean load_Z_BlockPos_J(BlockPos start, long blocked) {
      LongOpenHashSet seen = new LongOpenHashSet();
      LongArrayFIFOQueue queue = new LongArrayFIFOQueue();
      seen.add(start.asLong());
      queue.enqueue(start.asLong());

      while (!queue.isEmpty()) {
         long key = queue.dequeueLong();
         BlockPos p = BlockPos.of(key);
         if (this.isWithinFootprint(p.getX(), p.getZ()) || p.getY() > this.maxTargetY() || p.getY() < this.bounds.minY()) {
            return false;
         }

         if (seen.size() > 2048) {
            return false;
         }

         for (Direction d : Direction.values()) {
            BlockPos q = p.relative(d);
            long next = q.asLong();
            if (next != blocked && seen.add(next)) {
               BlockState state = this.view.getBlockState(q);
               if (state == PrintView.UNLOADED_SENTINEL) {
                  return false;
               }

               if (this.temporaryBlocks.containsKey(next) || init_Z_BlockState(state) || !state.isCollisionShapeFullBlock(this.view, q)) {
                  queue.enqueue(next);
               }
            }
         }
      }

      return true;
   }

