   private PrintCore.StanceRouteCandidate init_UiHelper_PacketUti_TokenStore_TaskQue(
      PrintNav.Inner_TaskQueue reach, int i, autismclient.ai.print.PrintClicks.Inner_DataUtil budget
   ) {
      PrintTarget t = this.targets[i];
      BlockPos c = t.pos();
      boolean memo = !this.view.hasHypotheses();
      long signature = memo ? this.init_J_TokenStore_TaskQue(reach, i, this.env.playerMotionState().position()) : 0L;
      if (memo) {
         long[] miss = this.sync_Int2ObjectOpenHash.get(i);
         if (miss != null && miss[1] == signature && this.init_Z_BlockPos_2(c, miss[0], 8)) {
            this.flags_J++;
            return null;
         }
      }

      boolean unsafe = false;
      LongArrayList candidates = new LongArrayList();

      for (int dx = -4; dx <= 4; dx++) {
         for (int dz = -4; dz <= 4; dz++) {
            for (int dy = -5; dy <= 3; dy++) {
               long key = BlockPos.asLong(c.getX() + dx, c.getY() + dy, c.getZ() + dz);
               if (reach.isReachable(key) && !this.open_LongOpenHashSet.contains(cellStanceKey(i, key)) && !this.failedWalkStances.contains(key)) {
                  candidates.add(key);
               }
            }
         }
      }

      candidates.sort((a, b) -> Double.compare(reach.costOf(a), reach.costOf(b)));

      for (long key : candidates) {
         if (budget.isExhausted()) {
            break;
         }

         if (!this.init_Z_I(i, reach.feetYOf(key), key)
            && (
               !this.write_Z_I(i)
                  || !(c.getY() >= reach.feetYOf(key) + 2.0)
                  || !this.temporaryBlocks
                     .containsKey(BlockPos.asLong(BlockPos.getX(key), (int)Math.floor(reach.feetYOf(key) - 0.001), BlockPos.getZ(key)))
            )) {
            for (Vec3 feet : PrintClicks.getCandidateFeetPositions(this.view, key, reach.feetYOf(key), PrintClicks.isOrientationSensitive(t, this.constraintFor(i)))) {
               autismclient.ai.print.PrintClicks.Inner_StreamUtil click = PrintClicks.findClick(
                  this.view,
                  this.env,
                  this.rules,
                  t,
                  t.item(),
                  PrintClicks.Inner_CachePool.PLACE,
                  feet,
                  false,
                  true,
                  budget,
                  4.1000000000000005
               );
               if (click != null && this.matchesPredictedState(t, click.predicted())) {
                  if (this.init_Z_TokenStore_TaskQue_J(reach, key)) {
                     this.logTrace("choose: standing click for " + c.toShortString() + " from " + BlockPos.of(key).toShortString());
                     IntArrayList cells = new IntArrayList();
                     cells.add(i);
                     this.sync_Int2ObjectOpenHash.remove(i);
                     return new PrintCore.StanceRouteCandidate(key, feet, false, reach.reconstructPath(key), cells, 1.0);
                  }

                  unsafe = true;
               }
            }
         }
      }

      if (memo && !unsafe && !budget.isExhausted()) {
         this.sync_Int2ObjectOpenHash.put(i, new long[]{this.view.worldMutationRevision(), signature});
      }

      return null;
   }

   boolean close_Z_I(int i) {
      long[] miss = this.flush_Int2ObjectOpenHash.get(i);
      return miss != null && this.reachable != null && !this.view.hasHypotheses()
         ? miss[1] == this.init_J_TokenStore_TaskQue(this.reachable, i, this.env.playerMotionState().position())
            && this.init_Z_BlockPos_2(this.targets[i].pos(), miss[0], 8)
         : false;
   }

   private long init_J_TokenStore_TaskQue(PrintNav.Inner_TaskQueue reach, int i, Vec3 body) {
      BlockPos c = this.targets[i].pos();
      long h = 1L + this.f_D_J * -7046029254386353131L;

      for (int dx = -4; dx <= 4; dx++) {
         for (int dz = -4; dz <= 4; dz++) {
            for (int dy = -5; dy <= 3; dy++) {
               long key = BlockPos.asLong(c.getX() + dx, c.getY() + dy, c.getZ() + dz);
               if (reach.isReachable(key)) {
                  h = h * 1000003L + key;
                  h = h * 31L + Double.doubleToLongBits(reach.feetYOf(key));
                  if (key == reach.startKey) {
                     h = h * 31L + Math.round(body.x * 64.0) * 7919L + Math.round(body.y * 64.0) * 31L + Math.round(body.z * 64.0);
                  }
               }
            }
         }
      }

      if (this.write_Z_I(i)) {
         this.init_Z_I_D(i, -1.0 / 0.0);
         int f = this.read_IArr[i];
         h = h * 31L + (this.load_ZArr[f] ? 1 : 2) + 4L * this.update_IArr[f];
      }

      return h;
   }

