   private LongArrayList init_LongArrayList_TokenStore_TaskQue(PrintNav.Inner_TaskQueue reach, BlockPos target, boolean walkFirst) {
      LongArrayList candidates = new LongArrayList();

      for (int dx = -4; dx <= 4; dx++) {
         for (int dz = -4; dz <= 4; dz++) {
            for (int dy = -5; dy <= 3; dy++) {
               long key = BlockPos.asLong(target.getX() + dx, target.getY() + dy, target.getZ() + dz);
               if (reach.isReachable(key) && (key == reach.startKey || !this.failedWalkStances.contains(key))) {
                  candidates.add(key);
               }
            }
         }
      }

      candidates.sort(
         (a, b) -> {
            double ca = walkFirst
               ? reach.costOf(a)
               : square(BlockPos.getX(a) - target.getX())
                  + square(BlockPos.getZ(a) - target.getZ())
                  + 0.25 * square(reach.feetYOf(a) + 1.27 - target.getY() - 0.5);
            double cb = walkFirst
               ? reach.costOf(b)
               : square(BlockPos.getX(b) - target.getX())
                  + square(BlockPos.getZ(b) - target.getZ())
                  + 0.25 * square(reach.feetYOf(b) + 1.27 - target.getY() - 0.5);
            int order = Double.compare(ca, cb);
            return order != 0 ? order : Long.compare(a, b);
         }
      );
      return candidates;
   }

