   boolean init_Z_I_I(int i, int lowest) {
      BlockPos p = this.targets[i].pos();
      if (p.getY() - 2 > lowest) {
         return false;
      }

      if (this.targets[i].wanted().getShape(this.view, p).isEmpty()) {
         return false;
      }

      for (int k = 1; k <= 2; k++) {
         BlockPos q = p.below(k);
         int qi = this.cellIndexByPos.get(q.asLong());
         if (qi >= 0) {
            if (this.cellStates[qi] != 0) {
               return false;
            }

            if (this.get(qi)
               && !this.sync_Z_I(qi)
               && !this.read_IntOpenHashSet.contains(qi)
               && this.targets[qi].kind() == autismclient.ai.print.PrintTarget.Inner_DataUtil.PLACE) {
               return q.getY() == lowest
                  && !this.poll_Z_BlockPos(q)
                  && this.env.canBlockSurvive(this.targets[qi].wanted(), q)
                  && !this.state(qi);
            }

            return false;
         }

         if (!this.view.getBlockState(q).isAir()) {
            return false;
         }
      }

      return false;
   }

