   private List<Long> init_List_BlockPos_Vec3(BlockPos here, Vec3 body) {
      ArrayList<Long> candidates = new ArrayList<>();
      if (this.buffer_LongOpenHashSet.isEmpty()) {
         return candidates;
      }

      for (long key : this.temporaryBlocks.keySet()) {
         if (this.buffer_LongOpenHashSet.contains(key)
            && BlockPos.getY(key) >= body.y - 0.6
            && (BlockPos.getX(key) != here.getX() || BlockPos.getZ(key) != here.getZ())) {
            candidates.add(key);
         }
      }

      if (candidates.isEmpty()) {
         return candidates;
      }

      LongOpenHashSet unchecked = new LongOpenHashSet(candidates);
      Vec3[] eyes = new Vec3[]{PrintGeometry.init(body, false), PrintGeometry.init(body, true)};

      for (long original : this.temporaryBlocks.keySet()) {
         if (!this.buffer_LongOpenHashSet.contains(original) && !this.sync_Z_J(original)) {
            Vec3 target = Vec3.atCenterOf(BlockPos.of(original));

            for (Vec3 eye : eyes) {
               if (!(eye.distanceToSqr(target) > 16.810000000000006)) {
                  BlockHitResult hit = this.view.raycastBlock(eye, target);
                  if (hit != null) {
                     unchecked.remove(hit.getBlockPos().asLong());
                  }
               }
            }

            if (unchecked.isEmpty()) {
               break;
            }
         }
      }

      candidates.removeIf(key -> unchecked.contains(key));
      return candidates;
   }

