   private String init_Str_BlockPos_NodeWalker_StreamU(BlockPos target, autismclient.ai.engine.AiPhysics.MotionState b) {
      StringBuilder out = new StringBuilder();
      int x0 = Math.min(target.getX(), (int)Math.floor(b.x())) - 1;
      int x1 = Math.max(target.getX(), (int)Math.floor(b.x())) + 1;
      int z0 = Math.min(target.getZ(), (int)Math.floor(b.z())) - 1;
      int z1 = Math.max(target.getZ(), (int)Math.floor(b.z())) + 1;
      int y0 = Math.min(target.getY(), (int)Math.floor(b.y())) - 3;
      int y1 = Math.max(target.getY(), (int)Math.floor(b.y())) + 3;

      for (int y = y0; y <= y1; y++) {
         for (int x = x0; x <= x1; x++) {
            for (int z = z0; z <= z1; z++) {
               BlockPos p = new BlockPos(x, y, z);
               if (!this.view.getCollisionShape(p).isEmpty()) {
                  BlockState st = this.view.getBlockState(p);
                  out.append(x)
                     .append(',')
                     .append(y)
                     .append(',')
                     .append(z)
                     .append('=')
                     .append(BuiltInRegistries.BLOCK.getKey(st.getBlock()).getPath())
                     .append(' ');
               }
            }
         }
      }

      return out.toString();
   }

