   private boolean init_Z_BlockPos_6(BlockPos at, BlockState expected, BlockState actual) {
      if (PrintRules.matchesLayout(expected, actual)) {
         return true;
      } else if (expected.is(Blocks.PISTON_HEAD) && actual.isAir()) {
         Direction direction = expected.getValue(PistonHeadBlock.FACING);
         BlockState base = this.view.getBlockState(at.relative(direction.getOpposite()));
         BlockState wantedBase = this.close_Long2ObjectOpenHas.get(at.relative(direction.getOpposite()).asLong());
         return wantedBase != null
            && wantedBase.getBlock() instanceof PistonBaseBlock
            && base.is(wantedBase.getBlock())
            && base.getValue(PistonBaseBlock.FACING) == direction
            && !base.getValue(PistonBaseBlock.EXTENDED);
      } else {
         return false;
      }
   }

