   boolean isWithinFootprint(int x, int z) {
      if (this.f_aw_I == 2147483647) {
         for (PrintTarget t : this.targets) {
            this.f_aw_I = Math.min(this.f_aw_I, t.pos().getX());
            this.f_ax_I = Math.max(this.f_ax_I, t.pos().getX());
            this.f_ay_I = Math.min(this.f_ay_I, t.pos().getZ());
            this.f_az_I = Math.max(this.f_az_I, t.pos().getZ());
         }
      }

      return x < this.f_aw_I || x > this.f_ax_I || z < this.f_ay_I || z > this.f_az_I;
   }

