   boolean read_Z_J(long key) {
      BlockPos floor = BlockPos.of(key).below();
      BlockState st = this.view.getBlockState(floor);
      if (st.isCollisionShapeFullBlock(this.view, floor)) {
         return false;
      } else {
         VoxelShape shape = this.view.getCollisionShape(floor);
         if (shape.isEmpty()) {
            BlockPos own = BlockPos.of(key);
            return !this.view.getBlockState(own).isCollisionShapeFullBlock(this.view, own)
               && !this.view.getCollisionShape(own).isEmpty()
               && this.view.getCollisionShape(own).bounds().getXsize() < 0.99;
         } else {
            AABB box = shape.bounds();
            return box.getXsize() < 0.99 || box.getZsize() < 0.99;
         }
      }
   }

