   boolean init_Z_I_2(int x, int y, int z) {
      BlockPos cell = new BlockPos(x, y, z);
      if (!this.view.getBlockState(cell).isAir()) {
         return false;
      }

      BlockPos floor = cell.below();
      VoxelShape shape = this.view.getCollisionShape(floor);
      if (shape.isEmpty()) {
         return false;
      }

      double floorTop = -1.0 / 0.0;
      double lo = 0.2;
      double hi = 0.8;

      for (AABB b : shape.toAabbs()) {
         if (b.maxX > lo && b.minX < hi && b.maxZ > lo && b.minZ < hi) {
            floorTop = Math.max(floorTop, floor.getY() + b.maxY);
         }
      }

      return floorTop >= y - 0.2;
   }

