   boolean run(BlockPos pos) {
      autismclient.ai.engine.AiPhysics.MotionState b = this.env.playerMotionState();
      VoxelShape shape = this.view.getCollisionShape(pos);
      if (shape.isEmpty()) {
         return false;
      }

      AABB under = new AABB(b.x() - 0.3, b.y() - 0.05, b.z() - 0.3, b.x() + 0.3, b.y() + 0.01, b.z() + 0.3);

      for (AABB box : shape.toAabbs()) {
         if (box.move(pos).intersects(under)) {
            return true;
         }
      }

      return false;
   }

