   private boolean init_Z_BlockPos_8(BlockPos pos, BlockState state, AABB body) {
      for (AABB box : this.view.getCollisionBoxesForState(state, pos)) {
         double top = pos.getY() + box.maxY;
         if (!(top > body.minY + 1.0E-4)
            && !(top < body.minY - 0.05)
            && pos.getX() + box.minX < body.maxX
            && pos.getX() + box.maxX > body.minX
            && pos.getZ() + box.minZ < body.maxZ
            && pos.getZ() + box.maxZ > body.minZ) {
            return true;
         }
      }

      return false;
   }

