   List<PrintCore.aB> load_List() {
      if (this.sync_List != null) {
         return this.sync_List;
      }

      this.sync_List = new ArrayList<>();
      this.push_Int2ObjectOpenHash = new Int2ObjectOpenHashMap<>();

      for (int i : this.load_IArr()) {
         BlockPos source = this.targets[i].pos();
         Fluid fluid = this.targets[i].wanted().getFluidState().getType();
         if (!this.cellIndexByPos.containsKey(source.below().asLong())
            || !this.init_Z_BlockPos_7(source.below(), this.load_BlockState_BlockPos(source.below()), fluid)) {
            ArrayList<BlockPos> outlets = new ArrayList<>();
            ArrayList<BlockPos> outside = new ArrayList<>();
            ArrayList<BlockPos> floors = new ArrayList<>();
            boolean supported = true;

            for (Direction direction : Plane.HORIZONTAL) {
               BlockPos next = source.relative(direction);
               BlockState boundary = this.load_BlockState_BlockPos(next);
               if (this.init_Z_BlockPos_7(next, boundary, fluid)) {
                  int at = this.cellIndexByPos.get(next.asLong());
                  int below = this.cellIndexByPos.get(next.below().asLong());
                  if (at >= 0) {
                     if (this.targets[at].kind() != autismclient.ai.print.PrintTarget.Inner_DataUtil.FLOW
                        || below < 0
                        || !this.targets[at].wanted().getFluidState().getType().isSame(fluid)
                        || !this.targets[below].wanted().getFluidState().getType().isSame(fluid)) {
                        supported = false;
                        break;
                     }

                     outlets.add(next);
                  } else {
                     if (!boundary.isAir()) {
                        supported = false;
                        break;
                     }

                     outside.add(next);
                     if (this.init_Z_BlockPos_7(next.below(), this.load_BlockState_BlockPos(next.below()), fluid)) {
                        if (below >= 0 || !this.load_BlockState_BlockPos(next.below()).isAir()) {
                           supported = false;
                           break;
                        }

                        floors.add(next.below());
                     }
                  }
               }
            }

            if (supported && !outlets.isEmpty() && !outside.isEmpty() && !floors.isEmpty()) {
               PrintCore.aB shape = new PrintCore.aB(i, List.copyOf(floors), List.copyOf(outside), List.copyOf(outlets));
               this.sync_List.add(shape);
               this.push_Int2ObjectOpenHash.put(i, shape);

               for (BlockPos floor : floors) {
                  this.add_Long2ObjectOpenHas.computeIfAbsent(floor.asLong(), ignored -> new ArrayList<>()).add(shape);
               }
            }
         }
      }

      return this.sync_List;
   }

